package demo; import java.util.*; import java.io.*; import java.nio.charset.StandardCharsets;
public class Probe { static String esc(String s){return s.replace("\\","\\\\").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t").replace("\f","\\f");} static String parse(String x,boolean reader)throws Exception{Properties p=new Properties();byte[] b=x.getBytes(StandardCharsets.UTF_8);if(reader)p.load(new InputStreamReader(new ByteArrayInputStream(b),StandardCharsets.UTF_8));else p.load(new ByteArrayInputStream(b));StringBuilder z=new StringBuilder();for(String k:new TreeSet<>(p.stringPropertyNames()))z.append(esc(k)).append('=').append(esc(p.getProperty(k))).append(';');return z.toString();} static String counted(){try{Properties p=new Properties();p.load(new ByteArrayInputStream("x=y".getBytes("ISO-8859-1")));return "counted:"+p.getProperty("x");}catch(Exception e){return e.getClass().getName()+":"+e.getMessage();}} public static String rows(){StringBuilder b=new StringBuilder();String[] xs={"a\\ b=c\n","a=one\\\n#two\n","a\\fb\n","a\u00a0b=c\n","a=b\r","a=\\u12G4\n","\\u12G4=x\n","e=é\n"};for(int i=0;i<xs.length;i++)for(boolean r:new boolean[]{true,false})try{b.append("x").append(i).append(r?'R':'I').append('=').append(parse(xs[i],r)).append('\n');}catch(Exception e){b.append("x").append(i).append(r?'R':'I').append('=').append(e.getClass().getName()).append(':').append(e.getMessage()).append('\n');}b.append("counted=").append(counted()).append('\n');return b.toString();}public static void main(String[]x){System.out.print(rows());}}
